const now = new Date();
const body = $json.body || {};
const prompt =
  body.prompt ||
  body.message ||
  $json.prompt ||
  $json.message ||
  $input.first().json.chatInput ||
  "";

if (!String(prompt).trim()) {
  throw new Error("Missing prompt/message in request body");
}

const sessionId = body.sessionId || body.session_id || "session-" + Date.now();
const userId = body.userId || body.user_id || "anonymous";
const requestId = body.requestId || "req-" + Date.now();

return [
  {
    json: {
      requestId: String(requestId),
      sessionId: String(sessionId),
      userId: String(userId),
      model: body.model || "models/gemini-2.5-flash",
      chatInput: String(prompt),
      startTs: now.getTime(),
      timestamp: now.toISOString(),
      source: "chat",
    },
  },
];

/*
