 * Copyright © 2026 Candid GRC Co., Ltd.
 * All Rights Reserved.
 *
 * This source code is proprietary and confidential.
 * Unauthorized copying, modification, redistribution,
 * reverse engineering, or commercial use is strictly prohibited.
 *
 * This code forms part of the Candid GRC Automation Framework.
 */

const req = $("Prepare Input + Start Timer").first().json;
const out = $input.first().json || {};

function safeNodeJson(nodeName) {
  try {
    return $(nodeName).first().json || {};
  } catch (e) {
    return {};
  }
}

function safeNodeJsonItems(nodeName) {
  try {
    return $(nodeName)
      .all()
      .map((item) => item.json || {});
  } catch (e) {
    return [];
  }
}

const modelItems = safeNodeJsonItems("Gemini 2.5 Flash");
const rawAgent = safeNodeJson("AI Agent");

function findUsage(obj, depth = 0) {
  if (!obj || typeof obj !== "object" || depth > 5) return null;

  const candidates = [
    obj.tokenUsage,
    obj.usageMetadata,
    obj.usage,
    obj.response?.usageMetadata,
    obj.response_metadata?.usage,
    obj.metadata?.usageMetadata,
    obj.metadata?.tokenUsage,
    obj.additional_kwargs?.usage,
    obj.additional_kwargs?.usageMetadata,
    obj.data?.usageMetadata,
    obj.data?.usage,
  ].filter(Boolean);

  for (const c of candidates) {
    if (typeof c === "object") return c;
  }

  for (const value of Object.values(obj)) {
    if (value && typeof value === "object") {
      const found = findUsage(value, depth + 1);
      if (found) return found;
    }
  }

  return null;
}

function firstUsageFromItems(items) {
  for (let i = items.length - 1; i >= 0; i--) {
    const found = findUsage(items[i]);
    if (found) return found;
  }
  return null;
}

function toNum(v, d = 0) {
  const n = Number(v);
  return Number.isFinite(n) ? n : d;
}

const usageFromChatModel = firstUsageFromItems(modelItems) || {};
const usageFromAgent = findUsage(rawAgent) || {};
const usageFromParsedOutput = findUsage(out) || {};
const usageFromAnswer =
  out.tokenUsage && typeof out.tokenUsage === "object" ? out.tokenUsage : {};

const usage = Object.keys(usageFromChatModel).length
  ? usageFromChatModel
  : Object.keys(usageFromAgent).length
    ? usageFromAgent
    : Object.keys(usageFromParsedOutput).length
      ? usageFromParsedOutput
      : usageFromAnswer;

const inputTokens = toNum(
  usage.promptTokens ??
    usage.promptTokenCount ??
    usage.inputTokens ??
    usage.prompt_tokens ??
    usage.input_tokens,
  0,
);
const outputTokens = toNum(
  usage.completionTokens ??
    usage.candidatesTokenCount ??
    usage.outputTokens ??
    usage.completion_tokens ??
    usage.output_tokens,
  0,
);
const totalTokens = toNum(
  usage.totalTokens ??
    usage.totalTokenCount ??
    usage.total_tokens ??
    usage.totalToken,
  inputTokens + outputTokens,
);

const claims = Array.isArray(out.factual_claims) ? out.factual_claims : [];
const unsupportedClaims = claims.filter((c) => {
  const status = String(c?.support_status || "").toLowerCase();
  return status === "unsupported" || status === "unknown";
}).length;
const hallucinationRate =
  claims.length > 0
    ? Number((unsupportedClaims / claims.length).toFixed(4))
    : null;

const responseText =
  out.answer || out.output || out.text || out.response || out.result || "";
const latencyMs = Date.now() - Number(req.startTs || Date.now());
const biasRisk = String(out.bias_risk || "unknown").toLowerCase();
const hallucinationRisk = String(
  out.hallucination_risk || "unknown",
).toLowerCase();

const autoNeedsReview =
  (hallucinationRate !== null && hallucinationRate > 0.2) ||
  biasRisk === "high" ||
  hallucinationRisk === "high";
const needsReview = Boolean(out.needs_review) || autoNeedsReview;

let tokenSource = "not-available";
if (Object.keys(usageFromChatModel).length) tokenSource = "chat-model-node";
else if (Object.keys(usageFromAgent).length)
  tokenSource = "agent-node-metadata";
else if (Object.keys(usageFromParsedOutput).length)
  tokenSource = "parsed-output-metadata";
else if (Object.keys(usageFromAnswer).length) tokenSource = "agent-self-report";

return [
  {
    json: {
      timestamp: new Date().toISOString(),
      execution_id: $execution.id,
      workflow_id: $workflow.id,
      request_id: req.requestId,
      session_id: req.sessionId,
      user_id: req.userId,
      model: req.model,
      prompt: req.chatInput,
      response: String(responseText),
      intent: out.intent || "",
      confidence: toNum(out.confidence, 0),
      assumptions: JSON.stringify(
        Array.isArray(out.assumptions) ? out.assumptions : [],
      ),
      evidence: JSON.stringify(Array.isArray(out.evidence) ? out.evidence : []),
      uncertainty: out.uncertainty || "",
      limitations: JSON.stringify(
        Array.isArray(out.limitations) ? out.limitations : [],
      ),
      factual_claim_count: claims.length,
      unsupported_claim_count: unsupportedClaims,
      hallucination_rate: hallucinationRate,
      hallucination_risk: hallucinationRisk,
      bias_risk: biasRisk,
      safety_risk: String(out.safety_risk || "unknown").toLowerCase(),
      needs_review: needsReview,
      review_reason:
        out.review_reason ||
        (autoNeedsReview ? "auto-threshold-triggered" : ""),
      latency_ms: latencyMs,
      status: "success",
      token_source: tokenSource,
    },
  },
];
